(() => {'use strict';let data=null;
 const words={seller:['مركز البائع','Seller center'],title:['لوحة متجرك','Store dashboard'],refresh:['تحديث','Refresh'],overview:['نظرة على نشاط متجرك','Your store at a glance'],addProduct:['إضافة منتج','Add product'],trend:['الطلبات خلال 14 يومًا','Orders over 14 days'],todo:['المتابعة اليوم','To do today'],latest:['أحدث الطلبات','Latest orders'],viewAll:['عرض الكل','View all'],codTitle:['مبالغ الطلبات المسلّمة','Delivered order amounts'],codNote:['سجل لقيمة الطلبات المسلّمة، وليس رصيدًا لدى BEMO أو إثباتًا لتحصيل النقد.','Recorded value of delivered orders; this is not a BEMO balance or confirmation of cash collection.'],products:['منتجات منشورة','Published products'],orders:['إجمالي الطلبات','Total orders'],pending:['بانتظار قرارك','Awaiting your decision'],lowStock:['خيارات بمخزون منخفض','Low-stock variants'],drafts:['مسودات منتجات','Product drafts'],empty:['لا توجد طلبات بعد.','No orders yet.'],noCod:['لا توجد طلبات مسلّمة بعد.','No delivered orders yet.'],view:['عرض','View'],periodTotal:['طلب خلال الفترة','orders in this period']};
 const states={PENDING_SELLER:['بانتظار القبول','Awaiting acceptance'],ESCALATED_TO_SUPPORT:['متابعة الدعم','Support review'],ACCEPTED:['مقبول','Accepted'],PACKING:['قيد التجهيز','Packing'],SHIPPED:['تم الشحن','Shipped'],DELIVERY_ATTEMPTED:['محاولة توصيل','Delivery attempted'],DELIVERED:['تم التسليم','Delivered'],REJECTED_BY_SELLER:['مرفوض','Rejected'],CANCELLED_BY_BUYER_PRE_ACCEPT:['ملغى','Cancelled'],CANCEL_REQUESTED:['طلب إلغاء','Cancellation requested'],RETURN_REQUESTED:['طلب إرجاع','Return requested'],RETURN_IN_REVIEW:['مراجعة الإرجاع','Return review'],RETURNED:['مرتجع','Returned'],CANCELLED_BY_SUPPORT:['ملغى بالدعم','Cancelled by support'],FAILED_DELIVERY:['تعذر التسليم','Delivery failed'],CLOSED:['مغلق','Closed']};
 const w=window.BemoWorkspace.create(words,{seller:true,onReady:()=>w.run(load),onClear:()=>{data=null;for(const id of ['metrics','trend','todo','recent','codTotals'])w.$(id).replaceChildren();w.$('shopTitle').textContent='';w.$('trendSummary').textContent='';},onLanguage:()=>{if(data)render();}}),$=w.$,n=w.node;
 async function load(req){data=await req('bemo_seller_dashboard');render();}
 function render(){$('shopTitle').textContent=data.store.title;$('addProduct').href=w.url('merchant.html',{new:'1'});$('ordersLink').href=w.url('orders.html',{view:'seller'});$('metrics').replaceChildren();for(const [key,value] of [['products',data.products],['orders',data.orders],['pending',data.pending],['lowStock',data.low_stock]]){const card=n('div',undefined,'metric');card.append(n('span',w.t(key)),n('strong',String(value)));$('metrics').append(card);}
  $('trend').replaceChildren();const max=Math.max(1,...data.trend.map(d=>d.orders));for(const day of data.trend){const b=n('div',undefined,'sales-bar');b.style.height=Math.max(2,day.orders/max*100)+'%';b.title=day.day+': '+day.orders;b.append(n('span',day.orders?String(day.orders):''));$('trend').append(b);}$('trend').setAttribute('aria-label',data.trend.map(d=>d.day+': '+d.orders).join(', '));$('trendSummary').textContent=data.trend.reduce((sum,d)=>sum+d.orders,0)+' '+w.t('periodTotal');
  $('todo').replaceChildren();for(const [key,count,file,params] of [['pending',data.pending,'orders.html',{view:'seller'}],['lowStock',data.low_stock,'merchant.html',{}],['drafts',data.drafts,'merchant.html',{}]]){const a=n('a');a.href=w.url(file,params);a.append(n('strong',String(count)),n('span',w.t(key)));$('todo').append(a);}
  $('recent').replaceChildren();if(!data.recent_orders.length)$('recent').append(n('p',w.t('empty'),'workspace-empty'));for(const o of data.recent_orders){const row=n('div',undefined,'recent-order'),a=n('a','#'+o.id.slice(0,8));a.href=w.url('orders.html',{view:'seller',id:o.id});row.append(a,n('span',(states[o.state]||[o.state,o.state])[w.lang()==='ar'?0:1],'order-pill'),n('strong',window.BemoLive.money(o.total_minor,o.currency,w.lang())),n('time',new Intl.DateTimeFormat(w.lang(),{month:'short',day:'numeric'}).format(new Date(o.created_at))));$('recent').append(row);}
  $('codTotals').replaceChildren();if(!data.cod_by_currency.length)$('codTotals').append(n('p',w.t('noCod'),'live-note'));for(const r of data.cod_by_currency)$('codTotals').append(n('span',window.BemoLive.money(r.total_minor,r.currency,w.lang())));
 }
 $('refresh').addEventListener('click',()=>w.run(load));w.start();
})();
